  },
  {
    "Domanda": "Quali browser sono consigliati per utilizzare ClassyFarm?",
    "Risposta": "È fortemente consigliato l’utilizzo di Google Chrome aggiornato all’ultima versione, per garantire la piena compatibilità con l’applicativo di ClassyFarm.",

"Categoria": "Avvertenze",
    "Contesto": "Requisiti tecnici"
  },
  {
    "Domanda": "Dove si trovano le guide e i moduli ufficiali di ClassyFarm?",
    "Risposta": "Tutti i manuali, le guide illustrate e i moduli ufficiali sono disponibili sul sito www.classyfarm.it nella sezione dedicata all’Operatore e ai suoi Delegati.",
    "Categoria": "Definizioni",
    "Contesto": "Documentazione ufficiale"
  }
]
[
  {
    "Domanda": "Come si richiede il profilo di Delegato da più operatori?",

}
]
[
  {
    "Domanda": "Come si richiede il profilo di Delegato da più operatori?",
    "Risposta": "La richiesta di accesso con la qualifica di Delegato da più operatori deve essere inviata al Ministero della Salute e in copia conoscenza a info@classyfarm.it, seguendo le modalità e utilizzando i documenti disponibili nella sezione 'Operatore e suoi Delegati' del sito www.classyfarm.it.",
    "Categoria": "Procedure",
    "Contesto": "Richiesta profilo Delegato da più operatori"
  },
  {
    "Domanda": "Quali obblighi ha il Delegato da più operatori una volta abilitato?",

},
  {
    "Domanda": "Quali obblighi ha il Delegato da più operatori una volta abilitato?",
    "Risposta": "Il Delegato da più operatori deve raccogliere, caricare e mantenere aggiornate in ClassyFarm le adesioni di ciascun operatore, operando nella sezione 'Selezione Azienda' del portale.",
    "Categoria": "Regole operative",
    "Contesto": "Gestione deleghe multiple"
  },
  {
    "Domanda": "Come accedere come Delegato da più operatori in ClassyFarm?",

},
  {
    "Domanda": "Come accedere come Delegato da più operatori in ClassyFarm?",
    "Risposta": "Per accedere come Delegato da più operatori, collegarsi a www.vetinfo.it, cliccare su 'Accedi all’area riservata', inserire le credenziali VetINFO, poi selezionare 'ClassyFarm 2.0' e infine scegliere il ruolo 'Delegato da più operatori'.",
    "Categoria": "Procedure",
    "Contesto": "Accesso Delegato multiplo"
  },
  {
    "Domanda": "Come iniziare a lavorare come Delegato da più operatori?",
    "Risposta": "Dopo l’accesso, cliccare su 'Selezione Azienda' per abbinarsi a un allevamento e su 'Dashboard' per visualizzare i cruscotti interattivi relativi agli operatori deleganti.",

"Categoria": "Comandi operativi",
    "Contesto": "Operatività Delegato multiplo"
